struct Base { virtual ~Base() = default; };   // 关键：析构 virtual
struct Derived : Base {
  int* buf = new int[64];
  ~Derived() override { delete[] buf; }   // 推荐显式 override
};
int main() { Base* p = new Derived; delete p; }  // 现在会先 ~Derived 再 ~Base

